def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    start = None
    candidates = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                start = (r, c)
            if grid[r][c] == 8:
                border = r in (0, h - 1) or c in (0, w - 1)
                near_blue = any(
                    0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 1
                    for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                    if dr or dc
                )
                if border or near_blue:
                    candidates.add((r, c))
    seen = {start}
    stack = [start]
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p in candidates and p not in seen:
                seen.add(p)
                stack.append(p)
    for r, c in seen:
        out[r][c] = 7
    out[start[0]][start[1]] = 6
    return out
